function nextBiggerSameDigits(n: number): number {
  const d = String(n).split("").map(Number);
  let i = d.length - 2;
  while (i >= 0 && d[i] >= d[i + 1]) i--;
  if (i < 0) return -1;
  let pick = i + 1;
  for (let j = i + 1; j < d.length; j++) if (d[j] > d[i] && d[j] <= d[pick]) pick = j;
  [d[i], d[pick]] = [d[pick], d[i]];
  const tail = d.slice(i + 1).sort((a, b) => a - b);
  const v = Number(d.slice(0, i + 1).join("") + tail.join(""));
  return v > 2147483647 ? -1 : v;
}

