class Solution:
    def nextBiggerSameDigits(self, n: int) -> int:
        d = list(str(n))
        i = len(d) - 2
        while i >= 0 and d[i] >= d[i + 1]:
            i -= 1
        if i < 0:
            return -1
        pick = min((c, -j) for j, c in enumerate(d) if j > i and c > d[i])
        j = -pick[1]
        d[i], d[j] = d[j], d[i]
        v = int("".join(d[:i + 1] + sorted(d[i + 1:])))
        return v if v <= 2**31 - 1 else -1

