function nextBiggerSameDigits(n: number): number {
  const d = String(n).split("");
  let i = d.length - 2;
  while (i >= 0 && d[i] >= d[i + 1]) i--;
  if (i < 0) return -1;
  let j = d.length - 1;
  while (d[j] <= d[i]) j--;
  [d[i], d[j]] = [d[j], d[i]];
  for (let a = i + 1, b = d.length - 1; a < b; a++, b--) [d[a], d[b]] = [d[b], d[a]];
  const v = Number(d.join(""));
  return v > 2147483647 ? -1 : v;
}

